/** What's in the can: a brewery's own hop list for each beer, with every hop
 *  opened up -- numbers, oils, aroma, where it's grown. data/beers/*.yml is
 *  generated by tools/ingest/beers.py from the brewery's beer pages. */

import { esc, fmt, shell, footer, tip } from './render.js';
import { caps, mineBlock, hopsInMyGlass, avg } from './mine.js';

const STATE_LABEL = { WA: 'Washington', OR: 'Oregon', ID: 'Idaho' };
const COUNTRY = { US: 'USA', NZ: 'New Zealand', AU: 'Australia', DE: 'Germany', CZ: 'Czechia', GB: 'England', SI: 'Slovenia', FR: 'France', PL: 'Poland', JP: 'Japan' };
const ROLE = { aroma: 'Aroma', bittering: 'Bittering', dual: 'Dual purpose' };
const OIL_COLOR = {
  myrcene: '#c8901a', humulene: '#3b6b4c', caryophyllene: '#9a4a2b', farnesene: '#6c7f4a',
  linalool: '#a8823f', geraniol: '#7e6a3c', pinene: '#2f5a4a', selinene: '#8a6d55', other: '#bcb7a4',
};

const roleOf = (hop) => (/purpose defaulted/.test(hop.meta?.notes ?? '') ? null : ROLE[hop.purpose]);

/** Collapse the brewery's list to one entry per variety, keeping every way
 *  it went in (T90, Cryo, fresh from a named farm...). */
export function hopBill(beer) {
  const bill = [];
  for (const h of beer.hops) {
    const key = h.hop ?? `?${h.name}`;
    let entry = bill.find((e) => e.key === key);
    if (!entry) bill.push((entry = { key, slug: h.hop, name: h.name, forms: [], fresh: null }));
    if (h.fresh) entry.fresh = { farm: h.farm ?? null };
    if (h.fresh) continue;
    const label = [h.form, h.product ? (h.form ? `(${h.product})` : h.product) : null].filter(Boolean).join(' ') || 'regular';
    if (!entry.forms.includes(label)) entry.forms.push(label);
    if (h.farm) entry.farm = h.farm;
  }
  // "regular" only means something next to another form of the same hop.
  for (const e of bill) if (e.forms.length === 1 && e.forms[0] === 'regular' && !e.fresh) e.forms = [];
  return bill;
}

/** slug -> [{ brewery, beer, fresh }] for the "In the glass" block on hop pages. */
export function beersByHop(breweries) {
  const out = {};
  for (const b of breweries) {
    for (const beer of b.beers) {
      for (const entry of hopBill(beer)) {
        if (!entry.slug) continue;
        (out[entry.slug] ??= []).push({ brewery: b.brewery, beer: { slug: beer.slug, name: beer.name, abv: beer.abv }, fresh: Boolean(entry.fresh), mine: beer.mine ?? null });
      }
    }
  }
  return out;
}

/** slug -> { beers, with: [[slug, n], …] }: which hops share a hop bill with
 *  this one across every beer on file, most often first. Counted from the
 *  breweries' own lists, so it's what PNW brewers actually do. */
export function pairingsByHop(breweries) {
  const out = {};
  for (const b of breweries) {
    for (const beer of b.beers) {
      const slugs = [...new Set(hopBill(beer).map((e) => e.slug).filter(Boolean))];
      if (slugs.length < 2) continue;
      for (const a of slugs) {
        const row = (out[a] ??= { beers: 0, with: new Map() });
        row.beers += 1;
        for (const o of slugs) if (o !== a) row.with.set(o, (row.with.get(o) ?? 0) + 1);
      }
    }
  }
  for (const k of Object.keys(out)) out[k] = { beers: out[k].beers, with: [...out[k].with.entries()].sort((x, y) => y[1] - x[1]) };
  return out;
}

/** Adds beer.like = up to five other beers with the closest hop bill
 *  (Jaccard over the hops on file, at least two shared, or the same single
 *  hop), other breweries first on a tie. */
export function attachLookalikes(breweries) {
  const all = [];
  for (const b of breweries) for (const beer of b.beers) {
    const set = new Set(hopBill(beer).map((e) => e.slug).filter(Boolean));
    if (set.size) all.push({ b, beer, set });
  }
  const byHop = new Map();
  all.forEach((x, i) => { for (const h of x.set) (byHop.get(h) ?? byHop.set(h, []).get(h)).push(i); });
  all.forEach((x, i) => {
    const shared = new Map();
    for (const h of x.set) for (const j of byHop.get(h)) if (j !== i) shared.set(j, (shared.get(j) ?? 0) + 1);
    const scored = [];
    for (const [j, n] of shared) {
      const y = all[j];
      if (y.beer.name === x.beer.name && y.b === x.b) continue;
      if (n < 2 && !(x.set.size === 1 && y.set.size === 1)) continue;
      scored.push({ j, n, score: n / (x.set.size + y.set.size - n) });
    }
    scored.sort((p, q) => q.score - p.score || q.n - p.n || Number(all[p.j].b !== x.b) < Number(all[q.j].b !== x.b) || 0);
    // Keep the list from being one brewery's back catalogue: at most two per brewery.
    const per = new Map();
    const pick = [];
    for (const c of scored) {
      const y = all[c.j];
      const k = y.b.brewery.slug;
      if ((per.get(k) ?? 0) >= 2) continue;
      per.set(k, (per.get(k) ?? 0) + 1);
      pick.push({ brewery: y.b.brewery, beer: { slug: y.beer.slug, name: y.beer.name, abv: y.beer.abv }, shared: [...x.set].filter((h) => y.set.has(h)), score: c.score });
      if (pick.length === 5) break;
    }
    if (pick.length) x.beer.like = pick;
  });
}

function likeBlock(beer, bySlug, base) {
  if (!beer.like?.length) return '';
  return `<section class="block like">
    <h2>Beers like this one <span class="fine">· the closest hop bills on file</span></h2>
    <ul class="beerlist compact">
      ${beer.like
        .map(
          (x) => `<li><a href="${base}beers/${x.brewery.slug}/${x.beer.slug}/">${esc(x.beer.name)}</a>
        <span class="fine">${esc(x.brewery.name)} · shares ${x.shared.map((h) => esc(bySlug[h]?.name ?? h)).join(', ')}</span></li>`
        )
        .join('\n      ')}
    </ul>
  </section>`;
}

// --------------------------------------------------------------- pieces

/** Alpha acid in words: what a beer drinker means by "how bitter". */
export function bitterWord(a) {
  if (!a) return null;
  const mid = (a.low + a.high) / 2;
  return mid < 5 ? 'Gentle' : mid < 9 ? 'Moderate' : mid < 13 ? 'High' : 'Very high';
}

function alphaBar(a) {
  if (!a) return '<p class="hc-none">No bitterness figures on file yet.</p>';
  const max = 20;
  const l = Math.min(a.low, max) / max * 100;
  const w = Math.max(1.5, (Math.min(a.high, max) - Math.min(a.low, max)) / max * 100);
  return `<div class="hc-metric"><span title="Alpha acid: what makes a hop bitter">Bitterness <b class="bw">${bitterWord(a)}</b></span>
      <span class="hc-track" aria-hidden="true"><span class="hc-span" style="left:${l.toFixed(1)}%;width:${w.toFixed(1)}%"></span></span>
      <b class="num">${fmt(a.low)}–${fmt(a.high)}% α</b></div>`;
}

function oilLine(o) {
  if (!o) return '';
  return `<div class="hc-metric"><span title="Total oil: the aromatic part of the hop, mL per 100 g">Aroma oil</span>
      <span class="hc-track" aria-hidden="true"><span class="hc-span oil" style="left:${(Math.min(o.low, 4) / 4 * 100).toFixed(1)}%;width:${Math.max(1.5, (Math.min(o.high, 4) - Math.min(o.low, 4)) / 4 * 100).toFixed(1)}%"></span></span>
      <b class="num">${fmt(o.low)}–${fmt(o.high)} mL</b></div>`;
}

function oilStrip(hop) {
  const p = hop.derived?.oil_profile?.normalized;
  if (!p) return '';
  const parts = Object.entries(p).sort((a, b) => b[1] - a[1]);
  const top = parts.filter(([k]) => k !== 'other').slice(0, 2).map(([k, v]) => `${k} ${Math.round(v)}%`).join(', ');
  return `<div class="hc-oils" title="Oil breakdown: ${esc(parts.map(([k, v]) => `${k} ${v}%`).join(', '))}">
      <span class="hc-strip" aria-hidden="true">${parts.map(([k, v]) => `<span style="flex:${v};background:${OIL_COLOR[k] ?? '#bcb7a4'}"></span>`).join('')}</span>
      <span class="hc-oil-note">Mostly ${esc(top)}</span></div>`;
}

function grownLine(hop) {
  const a = hop.acreage;
  if (!a) return '';
  const parts = Object.entries(a.acres)
    .map(([st, s]) => [st, s[a.latest]])
    .filter(([, v]) => typeof v === 'number' && v > 0)
    .sort((x, y) => y[1] - x[1])
    .map(([st, v]) => `<b class="num">${v.toLocaleString('en-US')}</b> ac ${STATE_LABEL[st] ?? st}`);
  return parts.length ? `<p class="hc-grown">Grown ${a.latest}: ${parts.join(' · ')}</p>` : '';
}

function hopCard(entry, hop, taxonomy, base) {
  if (!hop) {
    return `<li class="hopcard missing">
      <div class="hc-head"><h3>${esc(entry.name)}</h3></div>
      <p class="hc-none">Not in HopLove yet. <a href="https://github.com/bdgroves/hoplove/issues/new?title=${encodeURIComponent(`Add ${entry.name}`)}">Ask for it</a>.</p>
    </li>`;
  }
  const role = roleOf(hop);
  const tags = (hop.aroma?.tags ?? []).slice(0, 6).map((t) => taxonomy.aromaTags[t]?.label ?? t);
  const how = [
    entry.fresh ? `<span class="how fresh">Fresh hop${entry.fresh.farm ? `, from ${esc(entry.fresh.farm)}` : ''}</span>` : '',
    ...entry.forms.map((f) => `<span class="how">${esc(f)}</span>`),
    entry.farm ? `<span class="how">from ${esc(entry.farm)}</span>` : '',
  ].join('');
  return `<li class="hopcard" id="hop-${hop.slug}">
      <div class="hc-head">
        <h3><a href="${base}hops/${hop.slug}/">${esc(hop.name)}</a></h3>
        <span class="hc-meta">${esc(COUNTRY[hop.country] ?? hop.country)}${role ? ` · <span class="purpose" data-purpose="${hop.purpose}">${role}</span>` : ''}</span>
      </div>
      <div class="hc-how">${how}</div>
      ${tags.length ? `<p class="hc-aroma">${esc(tags.join(', '))}</p>` : '<p class="hc-none">No aroma descriptors on file yet.</p>'}
      ${alphaBar(hop.analytics?.alpha_acid)}
      ${oilLine(hop.analytics?.total_oil)}
      ${oilStrip(hop)}
      ${grownLine(hop)}
    </li>`;
}

/** Aroma tags across the whole bill, most shared first: a quick read of
 *  what the hops are pulling toward together. */
function togetherBlock(bill, bySlug, taxonomy) {
  const counts = new Map();
  for (const e of bill) {
    const hop = e.slug && bySlug[e.slug];
    for (const t of hop?.aroma?.tags ?? []) counts.set(t, (counts.get(t) ?? 0) + 1);
  }
  const known = bill.filter((e) => e.slug && bySlug[e.slug]);
  if (known.length < 2 || !counts.size) return '';
  const ranked = [...counts.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])).slice(0, 12);
  const origins = new Map();
  for (const e of known) {
    const c = bySlug[e.slug].country;
    origins.set(c, (origins.get(c) ?? 0) + 1);
  }
  const originText = [...origins.entries()].sort((a, b) => b[1] - a[1]).map(([c, n]) => `${n} from ${COUNTRY[c] ?? c}`).join(', ');
  return `<section class="block taste">
    <h2>What it'll taste like</h2>
    <ul class="tags together">
      ${ranked.map(([t, n]) => `<li${n > 1 ? ' class="shared"' : ''}>${esc(taxonomy.aromaTags[t]?.label ?? t)}${n > 1 ? ` <span class="num">×${n}</span>` : ''}</li>`).join('\n      ')}
    </ul>
    <p class="fine">What the ${known.length} hops smell like, most shared first — from the hop growers' and breeders' own notes, not the brewery's. ${esc(originText)}.</p>
  </section>`;
}

/** Brooks's Edit form (hidden for everyone else; see site/assets/edit.js):
 *  fixes to the brewery or the beer go to data/beers/overrides.yml. */
function editBlock(brewery, beer, bySlug) {
  const line = (h) =>
    [h.fresh ? 'Fresh' : '', h.name, h.form ?? '', h.farm ? `from ${h.farm}` : ''].filter(Boolean).join(' ');
  const f = (id, label, value, attrs = '') =>
    `<label class="ed-field"><span class="scan-label">${label}</span><input id="${id}" value="${esc(value ?? '')}" ${attrs}></label>`;
  return `<details class="block edit-beer" hidden data-brewery="${esc(brewery.slug)}" data-beer="${esc(beer.slug)}">
    <summary>✏️ Edit this beer</summary>
    <p class="fine">Fix anything the scan or the brewery's site got wrong. Saving files the change; the page updates in a couple of minutes.</p>
    <div class="ed-grid">
      ${f('ed-brewery-name', 'Brewery', brewery.name)}
      ${f('ed-brewery-city', 'Town', brewery.city === 'Unknown' ? '' : brewery.city, 'placeholder="Yakima"')}
      ${f('ed-brewery-state', 'State', brewery.state, 'maxlength="2" placeholder="WA"')}
      ${f('ed-brewery-url', 'Brewery website', brewery.url, 'placeholder="https://…"')}
      ${f('ed-name', 'Beer', beer.name)}
      ${f('ed-style', 'Style', beer.style, 'placeholder="Fresh Hop IPA"')}
      ${f('ed-abv', 'ABV %', beer.abv, 'inputmode="decimal" placeholder="6.5"')}
    </div>
    <label class="ed-field"><span class="scan-label">Hops, one per line (write "Fresh" in front for fresh hops, "from Farm" after for the farm)</span>
    <textarea id="ed-hops" rows="${Math.min(12, Math.max(4, beer.hops.length + 1))}">${esc(beer.hops.map(line).join('\n'))}</textarea></label>
    <p><button type="button" class="chip scan-go" id="ed-save">Save changes</button> <span class="fine" id="ed-status" role="status"></span></p>
  </details>
  <script src="../../../assets/edit.js" type="module"></script>`;
}

/** For anyone new to hop talk: the words on these cards, in a sentence each. */
const GLOSSARY = `<details class="block glossary">
    <summary>New to hop talk? What these words mean</summary>
    <dl>
      <dt>Bitterness (alpha acid)</dt><dd>How much bite a hop gives when it's boiled. Under 5% is gentle, 13%+ is a bruiser. It's why a West Coast IPA snaps and a pilsner doesn't.</dd>
      <dt>Aroma oil</dt><dd>The smelly part of the hop — where the citrus, pine and tropical fruit come from. More oil, more punch when it's added late or dry-hopped.</dd>
      <dt>Myrcene, humulene…</dt><dd>The main oils. Lots of myrcene reads fruity and resinous; humulene and caryophyllene read woody, herbal, spicy.</dd>
      <dt>Aroma / bittering / dual purpose</dt><dd>What brewers mostly use the hop for: smell, bite, or both.</dd>
      <dt>Fresh (wet) hop</dt><dd>Hops straight from the field into the beer, same day, never dried. Only at harvest, late August into October.</dd>
      <dt>Cryo, CGX, LupoMax, Incognito</dt><dd>The same hop, processed: concentrated powder or extract, for more aroma with less vegetal taste.</dd>
    </dl>
  </details>`;

// --------------------------------------------------------------- pages

export function renderBeer({ brewery, beer, bySlug, taxonomy, meta }) {
  const base = '../../../';
  const bill = hopBill(beer);
  const fresh = bill.some((e) => e.fresh);
  const cards = bill.map((e) => hopCard(e, e.slug ? bySlug[e.slug] : null, taxonomy, base)).join('\n    ');

  const body = `
<header class="masthead" style="padding-top:1.5rem">
  <div class="wrap">
    <nav class="nav" style="border-top:0;padding-top:0">
      <a href="${base}">All hops</a>
      <a href="${base}beers/">Beers</a>
      <a href="${base}beers/#${brewery.slug}">More from ${esc(brewery.name)}</a>
    </nav>
    <p class="kicker">${esc(brewery.name)}${brewery.city && brewery.city !== 'Unknown' ? ` · ${esc(brewery.city)}, ${esc(brewery.state)}` : ''}${beer.style ? ` · ${esc(beer.style)}` : ''}</p>
    <h1 class="page-title">${esc(beer.name)}</h1>
    <p class="standfirst">${beer.abv != null ? `<span class="num">${fmt(beer.abv)}%</span> ABV. ` : ''}${bill.length} hop${bill.length === 1 ? '' : 's'}${fresh ? `, ${bill.filter((e) => e.fresh).length === 1 ? 'one' : bill.filter((e) => e.fresh).length} of them straight off the bine` : ''} —
    here's what each one is and what it brings.</p>
    ${beer.mine ? `<p class="had-it"><a href="#rate">${beer.mine.rating ? caps(beer.mine.rating.stars) : '✓'} <span>${beer.mine.checkins.length ? `Brooks had it${beer.mine.checkins.length > 1 ? ` ${beer.mine.checkins.length} times` : ''}` : 'Brooks rated it'}</span></a></p>` : ''}
  </div>
</header>

<main id="main" class="wrap beer">
  ${fresh ? `<p class="callout fresh-note"><b>Fresh hop beer.</b> Fresh (or “wet”) hops go from the bine to the kettle within hours, never kilned. The figures below are for the dried hop; fresh ones carry the same oils in a greener, brighter form, and brewers use several times the weight.</p>` : ''}
  ${togetherBlock(bill, bySlug, taxonomy)}
  <section class="block">
    <h2>The hop bill</h2>
    <ul class="hopcards">
    ${cards}
    </ul>
    <p class="fine">In the order ${esc(brewery.name)} lists them: <q>${esc(beer.hops_as_written)}</q>.
    ${beer.scanned ? `Read off a ${esc(beer.scanned_from ?? 'photo')} of the ${beer.scanned_from === 'text' ? 'brewery\'s text' : 'can'} with <a href="${base}scan/">Scan a beer</a>, ${esc(beer.scanned)}.` : (beer.url ? `From <a href="${esc(beer.url)}">the brewery's page for this beer</a>.` : '')} Forms like Cryo and CO2 extract are
    the same variety processed differently.</p>
  </section>
  ${likeBlock(beer, bySlug, base)}
  ${editBlock(brewery, beer, bySlug)}
  <p class="fine say-hi">Something off with this beer, or know what’s in it? <a href="mailto:contact@brooksgroves.com?subject=${encodeURIComponent(`HopLove: ${beer.name} (${brewery.name})`)}">✉️ Email Brooks</a></p>
  ${tip('Know your hops now?')}
  ${GLOSSARY}
  ${mineBlock(brewery, beer, base)}
</main>
${footer(base, meta)}`;

  return shell({
    title: `${beer.name} by ${brewery.name}: the hops, explained | HopLove`,
    active: 'beers',
    description: `${beer.name} (${brewery.name}) is hopped with ${bill.map((e) => e.name).join(', ')}. What each hop is, what it smells like, and where it's grown.`,
    body,
    base,
  });
}

export function renderBeers({ breweries, bySlug, meta, recent = [] }) {
  const base = '../';
  const order = [...breweries].sort(
    (a, b) => b.brewery.state.localeCompare(a.brewery.state) || a.brewery.city.localeCompare(b.brewery.city) || a.brewery.name.localeCompare(b.brewery.name)
  );
  const hopName = (e) => (e.slug && bySlug[e.slug] ? bySlug[e.slug].name : e.name);
  const SHOW = 12; // rows per list before "Show all"
  const row = (b, beer, showBrewery = false, i = 0) => {
    const bill = hopBill(beer);
    const search = [beer.name, b.brewery.name, b.brewery.city, ...bill.map(hopName), bill.some((e) => e.fresh) ? 'fresh hop wet hop' : ''].join(' ').toLowerCase();
    const had = beer.mine ? ` <span class="had" title="${beer.mine.rating ? `Brooks rated it ${beer.mine.rating.stars}` : 'Brooks had it'}">${beer.mine.rating ? `● ${beer.mine.rating.stars}` : '✓'}</span>` : '';
    return `<li data-search="${esc(search)}"${i >= SHOW ? ' data-more' : ''}><a href="${b.brewery.slug}/${beer.slug}/"><b>${esc(beer.name)}</b>${had}</a>
          <span class="num fine">${showBrewery ? esc(b.brewery.name) : beer.abv != null ? `${fmt(beer.abv)}%` : ''}</span>
          <span class="beer-hops">${bill.map((e) => `<span${e.fresh ? ' class="fresh"' : ''}>${esc(hopName(e))}</span>`).join('')}</span></li>`;
  };

  // Fresh hop season gets its own list: those beers only exist for a few weeks.
  const fresh = order
    .flatMap((b) => b.beers.filter((beer) => hopBill(beer).some((e) => e.fresh)).map((beer) => [b, beer]))
    .map(([b, beer], i) => row(b, beer, true, i));
  const more = (n, what) =>
    n > SHOW ? `<button type="button" class="chip show-all">Show all ${n.toLocaleString('en-US')} ${what}</button>` : '';

  const cities = new Map();
  for (const b of order) {
    const key = `${b.brewery.city}, ${b.brewery.state}`;
    if (!cities.has(key)) cities.set(key, []);
    cities.get(key).push(b);
  }
  const jump = [...cities.entries()]
    .map(([city, list]) => `<div class="jump-city"><span>${esc(city)}</span>${list.map((b) => `<a class="chip" href="#${b.brewery.slug}">${esc(b.brewery.name)} <span class="num">${b.beers.length}</span></a>`).join('')}</div>`)
    .join('');

  const sections = order
    .map(
      (b) => `<section class="block brewery" id="${b.brewery.slug}">
    <h2>${esc(b.brewery.name)} <span class="fine">· ${esc(b.brewery.city)}, ${esc(b.brewery.state)} · ${b.beers.length} beer${b.beers.length === 1 ? '' : 's'}</span></h2>
    <ul class="beerlist">
      ${b.beers.map((beer, i) => row(b, beer, false, i)).join('\n      ')}
    </ul>
    ${more(b.beers.length, `from ${esc(b.brewery.name)}`)}
    <p class="fine">${b.beers.every((x) => x.scanned) ? `Read off cans and tap lists with <a href="${base}scan/">Scan a beer</a>` : `Hop lists from ${b.brewery.url ? `<a href="${esc(b.brewery.url)}">${esc(b.brewery.name)}</a>` : esc(b.brewery.name)}'s own beer pages`}, ${esc(b.retrieved)}.</p>
  </section>`
    )
    .join('\n');

  const total = order.reduce((n, b) => n + b.beers.length, 0);

  // Which hops these breweries reach for most: each beer counts a hop once.
  const use = new Map();
  for (const b of order) for (const beer of b.beers) for (const e of hopBill(beer)) if (e.slug) use.set(e.slug, (use.get(e.slug) ?? 0) + 1);
  const top = [...use.entries()].sort((x, y) => y[1] - x[1]).slice(0, 15);
  const topBlock = top.length
    ? `<section class="block most-used">
    <h2>The hops they reach for <span class="fine">· how many of these ${total} beers use each one</span></h2>
    <ol class="bars">
      ${top
        .map(([slug, n]) => `<li><span class="bar-name"><a href="${base}hops/${slug}/">${esc(bySlug[slug]?.name ?? slug)}</a></span>
        <span class="bar-track"><span class="bar-fill" style="width:${((n / top[0][1]) * 100).toFixed(1)}%;--mark:var(--gold)"></span></span>
        <span class="bar-val num">${n}</span><span class="bar-delta num">${Math.round((n / total) * 100)}%</span></li>`)
        .join('\n      ')}
    </ol>
  </section>`
    : '';
  const glass = myGlassBlocks({ breweries: order, bySlug, recent, base });
  const body = `
<header class="masthead" style="padding-top:1.5rem">
  <div class="wrap">
    <h1 class="page-title">What's in the can</h1>
    <p class="standfirst">Pick a beer, see its hops — what each one is, what it
    smells like, how hard it bitters, and where it was grown. ${total.toLocaleString('en-US')} beers from
    ${order.length} breweries across Washington and Oregon, hop lists straight from the brewery.</p>
  </div>
</header>
<main id="main" class="wrap beers">
  <div class="finder">
    <div>
      <label for="bq">Find a beer, a brewery or a hop</label>
      <input id="bq" type="search" autocomplete="off" placeholder="strata, vortex, pfriem…">
    </div>
    <p class="try">Try <button type="button" class="chip" data-q="fresh hop">fresh hop</button><button type="button" class="chip" data-q="citra">citra</button><button type="button" class="chip" data-q="strata">strata</button><button type="button" class="chip" data-q="nelson">nelson</button><button type="button" class="chip" data-q="seattle">seattle</button></p>
  </div>
  <p class="bq-count" id="bq-count" hidden></p>
  <details class="browse">
    <summary>Browse by brewery <span class="fine">· ${order.length} breweries, ${cities.size} towns</span></summary>
    <div class="jump">${jump}</div>
  </details>
  ${glass}
  ${topBlock}
  ${fresh.length ? `<section class="block fresh-season" id="fresh-hop">
    <h2>Fresh hop season <span class="fine">· ${fresh.length} beer${fresh.length === 1 ? '' : 's'} brewed with hops straight off the bine · <a href="${base}fresh-hop/">the full guide, with the farms →</a></span></h2>
    <ul class="beerlist">
      ${fresh.join('\n      ')}
    </ul>
    ${more(fresh.length, 'fresh hop beers')}
  </section>` : ''}
${sections}
</main>
${footer(base, meta)}
<script src="${base}assets/beers.js" type="module"></script>`;

  return shell({
    title: "What's in the can — beers and their hops, explained | HopLove",
    active: 'beers',
    description: `${total.toLocaleString('en-US')} Pacific Northwest beers with every hop in them opened up: aroma, alpha acid, oils and where it was grown.`,
    body,
    base,
  });
}

/** Block for a hop's own page: which beers it's in. Fresh-hop beers first,
 *  then a dozen more; the full list is a search on the beers page. */
export function hopBeersBlock(list, base, hopName = '') {
  if (!list?.length) return '';
  const had = list.filter((x) => x.mine);
  const sorted = [...list].sort((a, b) => Number(Boolean(b.mine)) - Number(Boolean(a.mine)) || (b.mine?.rating?.stars ?? 0) - (a.mine?.rating?.stars ?? 0) || Number(b.fresh) - Number(a.fresh));
  const shown = sorted.slice(0, Math.max(12, had.length));
  const breweries = new Set(list.map((x) => x.brewery.slug)).size;
  const stars = had.map((x) => x.mine.rating?.stars).filter((v) => v != null);
  const yours = had.length
    ? `<p class="had-it">Brooks has had ${had.length === 1 ? 'one of them' : `${had.length} of them`}${stars.length ? ` · ${caps(avg(stars))} <span class="fine">average${stars.length > 1 ? ` of ${stars.length}` : ''}</span>` : ''}</p>`
    : '';
  return `<section class="block" id="in-the-glass">
    <h2>In the glass <span class="fine">· ${list.length} beer${list.length === 1 ? '' : 's'} from ${breweries} brewer${breweries === 1 ? 'y' : 'ies'}</span></h2>
    ${yours}
    <ul class="beerlist compact">
      ${shown
        .map(
          (x) => `<li><a href="${base}beers/${x.brewery.slug}/${x.beer.slug}/">${esc(x.beer.name)}</a>
        <span class="fine">${esc(x.brewery.name)}${x.fresh ? ' · <span class="fresh">fresh hop</span>' : ''}${x.mine ? ` · <span class="had">${x.mine.rating ? caps(x.mine.rating.stars, { small: true }) : '✓ had it'}</span>` : ''}</span></li>`
        )
        .join('\n      ')}
    </ul>
    ${list.length > shown.length ? `<p class="fine"><a href="${base}beers/?q=${encodeURIComponent(hopName.toLowerCase())}">All ${list.length} beers with ${esc(hopName)} →</a></p>` : ''}
  </section>`;
}

/** On /beers/: the latest check-ins, and which hops keep ending up in the glass. */
function myGlassBlocks({ breweries, bySlug, recent, base }) {
  if (!recent.length) return '';
  const card = (c) => {
    const href = c.match
      ? `${c.match.brewery.slug}/${c.match.beer.slug}/`
      : `${base}scan/?brewery=${encodeURIComponent(c.brewery)}&beer=${encodeURIComponent(c.beer)}`;
    const hops = c.match ? hopBill(c.match.beer).filter((e) => e.slug).map((e) => bySlug[e.slug]?.name ?? e.name) : [];
    const stars = c.match?.beer.mine?.rating?.stars ?? c.rating;
    return `<li class="ci-card${c.match ? '' : ' unknown'}">
      <a href="${href}">${c.photo ? `<img src="${esc(c.photo)}" alt="" loading="lazy">` : '<span class="ci-noimg">🍺</span>'}</a>
      <div><p class="ci-when">${esc(String(c.date))}${stars != null ? ` · ${caps(stars, { small: true })}` : ''}</p>
      <h3><a href="${href}">${esc(c.beer)}</a></h3>
      <p class="fine">${esc(c.brewery)}</p>
      ${hops.length ? `<p class="beer-hops">${hops.map((h) => `<span>${esc(h)}</span>`).join('')}</p>` : `<p class="fine"><a href="${href}">Hops not on file — scan the can 📷</a></p>`}</div></li>`;
  };
  const shown = recent.slice(0, 8);
  const known = recent.filter((c) => c.match).length;

  const inGlass = [...hopsInMyGlass(breweries, hopBill).entries()]
    .map(([slug, r]) => ({ slug, ...r, avg: avg(r.rated) }))
    .sort((a, b) => (b.rated.length >= 2) - (a.rated.length >= 2) || (b.avg ?? 0) - (a.avg ?? 0) || b.beers - a.beers)
    .slice(0, 12);
  const most = Math.max(1, ...inGlass.map((r) => r.beers));
  const loved = inGlass.filter((r) => r.rated.length >= 2);
  const hopsBlock = inGlass.length
    ? `<section class="block in-my-glass">
    <h2>${loved.length ? 'Hops Brooks loves' : 'Hops in Brooks’s glass'} <span class="fine">· ${loved.length ? 'average rating of the beers he’s had with each (two or more rated)' : 'how many of the beers he’s had use each one'}</span></h2>
    <ol class="bars">
      ${inGlass
        .map(
          (r) => `<li><span class="bar-name"><a href="${base}hops/${r.slug}/">${esc(bySlug[r.slug]?.name ?? r.slug)}</a></span>
        <span class="bar-track"><span class="bar-fill" style="width:${((r.avg != null && loved.length ? r.avg / 5 : r.beers / most) * 100).toFixed(1)}%;--mark:var(--rust)"></span></span>
        <span class="bar-val num">${r.avg != null && loved.length ? r.avg : r.beers}</span><span class="bar-delta num">${r.beers} beer${r.beers === 1 ? '' : 's'}</span></li>`
        )
        .join('\n      ')}
    </ol>
    ${loved.length ? '' : '<p class="fine">Once more of these are rated, this turns into the hops he loves, ranked.</p>'}
  </section>`
    : '';

  return `<section class="block my-recent" id="brooks-glass">
    <h2>In Brooks’s glass <span class="fine">· his latest Untappd check-ins, ${known} of ${recent.length} matched to their hops</span></h2>
    <ul class="ci-cards">
      ${shown.map(card).join('\n      ')}
    </ul>
  </section>
  ${hopsBlock}`;
}

/** /fresh-hop/: every fresh (wet) hop beer on file, by brewery, with the
 *  hops and farms behind them. A seasonal page worth sharing each fall. */
export function renderFreshHop({ breweries, bySlug, meta }) {
  const base = '../';
  const order = [...breweries].sort(
    (a, b) => b.brewery.state.localeCompare(a.brewery.state) || a.brewery.city.localeCompare(b.brewery.city) || a.brewery.name.localeCompare(b.brewery.name)
  );
  const hopName = (e) => (e.slug && bySlug[e.slug] ? bySlug[e.slug].name : e.name);
  const groups = order
    .map((b) => ({ b, beers: b.beers.filter((beer) => hopBill(beer).some((e) => e.fresh)) }))
    .filter((g) => g.beers.length);
  const total = groups.reduce((n, g) => n + g.beers.length, 0);

  // Which hops go in fresh, and which farms get named.
  const byHop = new Map();
  const farms = new Map();
  for (const g of groups) {
    for (const beer of g.beers) {
      for (const e of hopBill(beer)) {
        if (!e.fresh) continue;
        if (e.slug) byHop.set(e.slug, (byHop.get(e.slug) ?? 0) + 1);
        const farm = e.fresh.farm;
        if (farm) {
          const f = farms.get(farm) ?? { n: 0, hops: new Set(), breweries: new Set() };
          f.n += 1;
          f.hops.add(hopName(e));
          f.breweries.add(g.b.brewery.name);
          farms.set(farm, f);
        }
      }
    }
  }
  const topHops = [...byHop.entries()].sort((a, b) => b[1] - a[1]).slice(0, 12);
  const farmList = [...farms.entries()].sort((a, b) => b[1].n - a[1].n);
  const had = groups.flatMap((g) => g.beers.filter((beer) => beer.mine)).length;

  const row = (b, beer) => {
    const bill = hopBill(beer);
    const fresh = bill.filter((e) => e.fresh);
    const rest = bill.filter((e) => !e.fresh);
    const farmsHere = [...new Set(fresh.map((e) => e.fresh.farm).filter(Boolean))];
    const mine = beer.mine ? ` <span class="had">${beer.mine.rating ? caps(beer.mine.rating.stars, { small: true }) : '✓ Brooks had it'}</span>` : '';
    return `<li><a href="${base}beers/${b.brewery.slug}/${beer.slug}/"><b>${esc(beer.name)}</b></a>${mine}
        <span class="fh-hops"><span class="fresh">${fresh.map((e) => esc(hopName(e))).join(', ')}</span>${rest.length ? ` <span class="fine">+ ${rest.map((e) => esc(hopName(e))).join(', ')}</span>` : ''}${farmsHere.length ? ` <span class="fine">· from ${farmsHere.map(esc).join(', ')}</span>` : ''}</span></li>`;
  };

  const body = `
<header class="masthead" style="padding-top:1.5rem">
  <div class="wrap">
    <h1 class="page-title">Fresh hop <em>season</em></h1>
    <p class="standfirst">Once a year, late August into October, Northwest brewers drive to the hop farms,
    load up hops that were on the bine that morning, and get them into beer before they wilt. No drying,
    no pellets. Here are ${total} of those beers from ${groups.length} breweries — and the hops and farms behind them.</p>
  </div>
</header>
<main id="main" class="wrap beers fresh-guide">
  <section class="block">
    <h2>What fresh hop means</h2>
    <p class="fh-lede">Normal hops are kilned dry within hours of picking so they keep. Fresh (or "wet") hops skip that:
    they're mostly water, so brewers use four to six times as much, and the beer tastes greener and brighter — grassy,
    juicy, a bit like walking through the field. They don't keep, so drink them young.
    ${had ? `Brooks has had ${had} of these so far.` : ''}</p>
  </section>

  ${topHops.length ? `<section class="block most-used">
    <h2>The hops that go in fresh <span class="fine">· how many of these ${total} beers use each one straight off the bine</span></h2>
    <ol class="bars">
      ${topHops
        .map(([slug, n]) => `<li><span class="bar-name"><a href="${base}hops/${slug}/">${esc(bySlug[slug]?.name ?? slug)}</a></span>
        <span class="bar-track"><span class="bar-fill" style="width:${((n / topHops[0][1]) * 100).toFixed(1)}%;--mark:var(--sage)"></span></span>
        <span class="bar-val num">${n}</span></li>`)
        .join('\n      ')}
    </ol>
  </section>` : ''}

  ${farmList.length ? `<section class="block">
    <h2>The farms <span class="fine">· named by the breweries</span></h2>
    <ul class="fh-farms">
      ${farmList
        .map(([farm, f]) => `<li><b>${esc(farm)}</b> <span class="fine">${f.n} beer${f.n === 1 ? '' : 's'} · ${[...f.hops].map(esc).join(', ')} · for ${[...f.breweries].map(esc).join(', ')}</span></li>`)
        .join('\n      ')}
    </ul>
  </section>` : ''}

  ${groups
    .map(
      (g) => `<section class="block brewery" id="${g.b.brewery.slug}">
    <h2>${esc(g.b.brewery.name)} <span class="fine">· ${esc(g.b.brewery.city)}, ${esc(g.b.brewery.state)} · ${g.beers.length}</span></h2>
    <ul class="fh-list">
      ${g.beers.map((beer) => row(g.b, beer)).join('\n      ')}
    </ul>
  </section>`
    )
    .join('\n  ')}
  <p class="fine">Green hops were added fresh; the rest of the bill follows in grey. Lists come from each brewery's own
  site and are refreshed twice a week, so new releases turn up as the season goes. Some beers are from past seasons.</p>
  ${tip('Found your fresh hop fix?')}
</main>
${footer(base, meta)}`;

  return shell({
    title: `Fresh hop season: ${total} Northwest fresh hop beers and their hops | HopLove`,
    active: 'fresh',
    description: `${total} fresh (wet) hop beers from ${groups.length} Pacific Northwest breweries, with the hops that went in straight off the bine and the farms they came from.`,
    body,
    base,
  });
}
